  console.log("Most recent June dates:", gameDates.juneResults.map(r => ({ date: r.date, events: r.events.map(e => e.name) })));
}
if (gameDates.julyResults.length > 0) {
  console.log("July dates:", gameDates.julyResults.map(r => ({ date: r.date, events: r.events.map(e => e.name) })));
}
if (gameDates.mayResults.length > 0) {
  console.log("May dates (sample):", gameDates.mayResults.slice(0, 3).map(r => ({ date: r.date, events: r.events.map(e => e.name) })));
}
